mapper.select:
SELECT * FROM geographic_features

    is_active = true
    AND feature_type = #{featureType}
    AND region = #{region}
    AND grade_level = #{gradeLevel}
    AND textbook = #{textbook}
    AND source_type = #{sourceType}
    AND category = #{category}

ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT * FROM geographic_features
WHERE is_active = true AND (name LIKE CONCAT('%', #{query}, '%') OR description LIKE CONCAT('%', #{query}, '%'))
LIMIT #{limit}
